// 7×7 Gaussian blur kernel (uses clamp-to-edge but no local memory optimization)
__kernel void gaussianBlur7x7(
    __global const float* input,
    __global float* output,
    const int width,
    const int height,
    const float sigma)
{
    int gx = get_global_id(0);
    int gy = get_global_id(1);
    if (gx >= width || gy >= height) return;

    // Fixed 7×7 Gaussian weights (sigma = 1.4)
    const float weights[7][7] = {
        {0.00000067f, 0.00002292f, 0.00019117f, 0.00038771f, 0.00019117f, 0.00002292f, 0.00000067f},
        {0.00002292f, 0.00078633f, 0.00655965f, 0.01330373f, 0.00655965f, 0.00078633f, 0.00002292f},
        {0.00019117f, 0.00655965f, 0.05472157f, 0.11098164f, 0.05472157f, 0.00655965f, 0.00019117f},
        {0.00038771f, 0.01330373f, 0.11098164f, 0.22508352f, 0.11098164f, 0.01330373f, 0.00038771f},
        {0.00019117f, 0.00655965f, 0.05472157f, 0.11098164f, 0.05472157f, 0.00655965f, 0.00019117f},
        {0.00002292f, 0.00078633f, 0.00655965f, 0.01330373f, 0.00655965f, 0.00078633f, 0.00002292f},
        {0.00000067f, 0.00002292f, 0.00019117f, 0.00038771f, 0.00019117f, 0.00002292f, 0.00000067f}
    };

    float sum = 0.0f;
    for (int i = -3; i <= 3; i++) {
        for (int j = -3; j <= 3; j++) {
            int x = clamp(gx + j, 0, width - 1);
            int y = clamp(gy + i, 0, height - 1);
